package com.example.dealership.document;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;

import com.example.dealership.error.ConflictException;
import com.example.dealership.error.NotFoundException;
import com.example.dealership.vehicle.VehicleRepository;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class DocumentServiceTest {

    private static final String NUMBER = "FV/2026/10/118";
    private static final String OTHER_NUMBER = "OC-7781-2026";

    @Mock
    private DocumentRepository documentRepository;

    @Mock
    private VehicleRepository vehicleRepository;

    @InjectMocks
    private DocumentService documentService;

    @Test
    void findAllReturnsMappedDocumentsOfVehicle() {
        when(vehicleRepository.existsById(1L)).thenReturn(true);
        when(documentRepository.findAllByVehicleIdOrderById(1L))
                .thenReturn(List.of(document(NUMBER, DocumentStatus.PENDING), document(OTHER_NUMBER, DocumentStatus.REJECTED)));

        List<DocumentResponse> responses = documentService.findAll(1L);

        assertThat(responses).extracting(DocumentResponse::number).containsExactly(NUMBER, OTHER_NUMBER);
    }

    @Test
    void findAllThrowsNotFoundWhenVehicleDoesNotExist() {
        when(vehicleRepository.existsById(99L)).thenReturn(false);

        assertThatThrownBy(() -> documentService.findAll(99L))
                .isInstanceOf(NotFoundException.class)
                .hasMessage("Vehicle with id 99 not found");
    }

    @Test
    void createSavesPendingDocumentForVehicle() {
        when(vehicleRepository.existsById(1L)).thenReturn(true);
        when(documentRepository.existsByVehicleIdAndTypeAndStatusNot(1L, DocumentType.OC_POLICY, DocumentStatus.REJECTED))
                .thenReturn(false);
        when(documentRepository.save(any(Document.class))).thenAnswer(invocation -> invocation.getArgument(0));

        DocumentResponse response = documentService.create(1L, request());

        assertThat(response.vehicleId()).isEqualTo(1L);
        assertThat(response.type()).isEqualTo(DocumentType.OC_POLICY);
        assertThat(response.number()).isEqualTo(NUMBER);
        assertThat(response.issueDate()).isEqualTo(LocalDate.of(2026, 10, 20));
        assertThat(response.expiryDate()).isEqualTo(LocalDate.of(2027, 10, 19));
        assertThat(response.status()).isEqualTo(DocumentStatus.PENDING);
    }

    @Test
    void createThrowsConflictWhenActiveDocumentOfTypeAlreadyExists() {
        when(vehicleRepository.existsById(1L)).thenReturn(true);
        when(documentRepository.existsByVehicleIdAndTypeAndStatusNot(1L, DocumentType.OC_POLICY, DocumentStatus.REJECTED))
                .thenReturn(true);

        assertThatThrownBy(() -> documentService.create(1L, request()))
                .isInstanceOf(ConflictException.class)
                .hasMessage("Vehicle with id 1 already has an active OC_POLICY document");
        verify(documentRepository, never()).save(any());
    }

    @Test
    void createThrowsNotFoundWhenVehicleDoesNotExist() {
        when(vehicleRepository.existsById(99L)).thenReturn(false);

        assertThatThrownBy(() -> documentService.create(99L, request()))
                .isInstanceOf(NotFoundException.class)
                .hasMessage("Vehicle with id 99 not found");
        verify(documentRepository, never()).save(any());
    }

    @Test
    void changeStatusUpdatesExistingDocument() {
        Document document = document(NUMBER, DocumentStatus.PENDING);
        when(vehicleRepository.existsById(1L)).thenReturn(true);
        when(documentRepository.findByIdAndVehicleId(5L, 1L)).thenReturn(Optional.of(document));
        when(documentRepository.save(document)).thenReturn(document);

        DocumentResponse response = documentService.changeStatus(1L, 5L, new DocumentStatusRequest(DocumentStatus.VERIFIED));

        assertThat(response.status()).isEqualTo(DocumentStatus.VERIFIED);
        assertThat(document.getStatus()).isEqualTo(DocumentStatus.VERIFIED);
        verify(documentRepository).save(document);
    }

    @Test
    void changeStatusThrowsNotFoundWhenVehicleDoesNotExist() {
        when(vehicleRepository.existsById(99L)).thenReturn(false);

        assertThatThrownBy(() -> documentService.changeStatus(99L, 5L, new DocumentStatusRequest(DocumentStatus.VERIFIED)))
                .isInstanceOf(NotFoundException.class)
                .hasMessage("Vehicle with id 99 not found");
    }

    @Test
    void changeStatusThrowsNotFoundWhenDocumentDoesNotExistOrBelongsToAnotherVehicle() {
        when(vehicleRepository.existsById(1L)).thenReturn(true);
        when(documentRepository.findByIdAndVehicleId(99L, 1L)).thenReturn(Optional.empty());

        assertThatThrownBy(() -> documentService.changeStatus(1L, 99L, new DocumentStatusRequest(DocumentStatus.VERIFIED)))
                .isInstanceOf(NotFoundException.class)
                .hasMessage("Document with id 99 not found");
        verify(documentRepository, never()).save(any());
    }

    private static Document document(String number, DocumentStatus status) {
        return new Document(1L, DocumentType.OC_POLICY, number,
                LocalDate.of(2026, 10, 20), LocalDate.of(2027, 10, 19), status);
    }

    private static DocumentRequest request() {
        return new DocumentRequest(DocumentType.OC_POLICY, NUMBER, LocalDate.of(2026, 10, 20), LocalDate.of(2027, 10, 19));
    }
}

package com.example.dealership.document;

import static org.assertj.core.api.Assertions.assertThat;

import java.time.LocalDate;

import com.example.dealership.vehicle.FuelType;
import com.example.dealership.vehicle.Vehicle;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;
import org.springframework.boot.test.autoconfigure.orm.jpa.TestEntityManager;

@DataJpaTest
class DocumentRepositoryTest {

    @Autowired
    private DocumentRepository documentRepository;

    @Autowired
    private TestEntityManager entityManager;

    private Long vehicleId;
    private Long otherVehicleId;

    @BeforeEach
    void setUp() {
        vehicleId = entityManager.persistAndGetId(
                new Vehicle("WF0XXXGCDX0000004", "Ford", "Focus", 2026, FuelType.ELECTRIC, null), Long.class);
        otherVehicleId = entityManager.persistAndGetId(
                new Vehicle("WF0XXXGCDX0000005", "Ford", "Puma", 2025, FuelType.HYBRID, null), Long.class);
    }

    @Test
    void findAllByVehicleIdOrderByIdReturnsOnlyDocumentsOfThatVehicle() {
        Document first = documentRepository.save(document(vehicleId, DocumentType.INVOICE, DocumentStatus.PENDING));
        Document second = documentRepository.save(document(vehicleId, DocumentType.COC, DocumentStatus.REJECTED));
        documentRepository.save(document(otherVehicleId, DocumentType.INVOICE, DocumentStatus.PENDING));
        entityManager.flush();

        assertThat(documentRepository.findAllByVehicleIdOrderById(vehicleId))
                .extracting(Document::getId)
                .containsExactly(first.getId(), second.getId());
    }

    @Test
    void findByIdAndVehicleIdIgnoresDocumentOfAnotherVehicle() {
        Document document = documentRepository.save(document(vehicleId, DocumentType.INVOICE, DocumentStatus.PENDING));
        entityManager.flush();

        assertThat(documentRepository.findByIdAndVehicleId(document.getId(), vehicleId)).contains(document);
        assertThat(documentRepository.findByIdAndVehicleId(document.getId(), otherVehicleId)).isEmpty();
    }

    @Test
    void existsByVehicleIdAndTypeAndStatusNotFindsOnlyActiveDocumentsOfThatVehicle() {
        documentRepository.save(document(vehicleId, DocumentType.INVOICE, DocumentStatus.VERIFIED));
        documentRepository.save(document(vehicleId, DocumentType.COC, DocumentStatus.REJECTED));
        documentRepository.save(document(otherVehicleId, DocumentType.OC_POLICY, DocumentStatus.PENDING));
        entityManager.flush();

        assertThat(documentRepository.existsByVehicleIdAndTypeAndStatusNot(
                vehicleId, DocumentType.INVOICE, DocumentStatus.REJECTED)).isTrue();
        assertThat(documentRepository.existsByVehicleIdAndTypeAndStatusNot(
                vehicleId, DocumentType.COC, DocumentStatus.REJECTED)).isFalse();
        assertThat(documentRepository.existsByVehicleIdAndTypeAndStatusNot(
                vehicleId, DocumentType.OC_POLICY, DocumentStatus.REJECTED)).isFalse();
    }

    @Test
    void saveStoresDocumentThatCanBeReadBack() {
        Document saved = documentRepository.save(new Document(vehicleId, DocumentType.OC_POLICY, "OC-7781-2026",
                LocalDate.of(2026, 10, 20), LocalDate.of(2027, 10, 19), DocumentStatus.PENDING));
        entityManager.flush();
        entityManager.clear();

        Document found = documentRepository.findById(saved.getId()).orElseThrow();

        assertThat(found).isNotSameAs(saved);
        assertThat(found.getVehicleId()).isEqualTo(vehicleId);
        assertThat(found.getType()).isEqualTo(DocumentType.OC_POLICY);
        assertThat(found.getNumber()).isEqualTo("OC-7781-2026");
        assertThat(found.getIssueDate()).isEqualTo(LocalDate.of(2026, 10, 20));
        assertThat(found.getExpiryDate()).isEqualTo(LocalDate.of(2027, 10, 19));
        assertThat(found.getStatus()).isEqualTo(DocumentStatus.PENDING);
    }

    @Test
    void deletingVehicleDeletesItsDocuments() {
        Document document = documentRepository.save(document(vehicleId, DocumentType.INVOICE, DocumentStatus.PENDING));
        entityManager.flush();
        entityManager.clear();

        entityManager.remove(entityManager.find(Vehicle.class, vehicleId));
        entityManager.flush();
        entityManager.clear();

        assertThat(documentRepository.findById(document.getId())).isEmpty();
    }

    private static Document document(Long vehicleId, DocumentType type, DocumentStatus status) {
        return new Document(vehicleId, type, "NR-1", LocalDate.of(2026, 10, 1), null, status);
    }
}

package com.example.dealership.document;

import static org.assertj.core.api.Assertions.assertThat;

import java.time.Clock;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.Set;

import jakarta.validation.ConstraintViolation;
import jakarta.validation.Validation;
import jakarta.validation.Validator;
import jakarta.validation.ValidatorFactory;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

// Date rules of the request with a fixed "today" (INTENT A5, Z5, Z12).
class DocumentRequestValidationTest {

    private static final LocalDate TODAY = LocalDate.of(2026, 11, 15);

    private ValidatorFactory factory;
    private Validator validator;

    @BeforeEach
    void setUp() {
        Clock clock = Clock.fixed(TODAY.atStartOfDay().toInstant(ZoneOffset.UTC), ZoneOffset.UTC);
        factory = Validation.byDefaultProvider().configure().clockProvider(() -> clock).buildValidatorFactory();
        validator = factory.getValidator();
    }

    @AfterEach
    void tearDown() {
        factory.close();
    }

    @Test
    void issueDateTodayIsValid() {
        assertThat(validate(TODAY, null)).isEmpty();
    }

    @Test
    void issueDateTomorrowIsRejected() {
        assertThat(validate(TODAY.plusDays(1), null))
                .extracting(violation -> violation.getPropertyPath().toString(), ConstraintViolation::getMessage)
                .containsExactly(org.assertj.core.groups.Tuple.tuple(
                        "issueDate", "must be a date in the past or in the present"));
    }

    @Test
    void expiryDateEqualToIssueDateIsValid() {
        assertThat(validate(TODAY, TODAY)).isEmpty();
    }

    @Test
    void expiryDateInThePastIsValid() {
        assertThat(validate(TODAY.minusYears(2), TODAY.minusYears(1))).isEmpty();
    }

    @Test
    void expiryDateBeforeIssueDateIsRejectedOnExpiryDate() {
        assertThat(validate(TODAY, TODAY.minusDays(1)))
                .extracting(violation -> violation.getPropertyPath().toString(), ConstraintViolation::getMessage)
                .containsExactly(org.assertj.core.groups.Tuple.tuple("expiryDate", "must not be before issue date"));
    }

    private Set<ConstraintViolation<DocumentRequest>> validate(LocalDate issueDate, LocalDate expiryDate) {
        return validator.validate(new DocumentRequest(DocumentType.OC_POLICY, "OC-1", issueDate, expiryDate));
    }
}

